  assert.equal((await post(t, '/auth/logout', '', { _csrf: csrf })).status, 403);
  assert.deepEqual(t.guilds.allowedChannels(G), []);
  const ok = await post(t, path, session, { _csrf: csrf, allowed: '400000000000000001', task_channel: '' });
